    kind: 'check',
    scope: 'full',
    complete: true,
    artifact: { path: 'evidence/check.json', sha256: H },
    bindings: { sourceSha256: H, configSha256: H },
  })
  assert.equal(
    (await verifyApplicability(plan, { boundary, snapshot: { sourceSha256: H, configSha256: H } }))
